// @ts-check

import { Command } from '../../utils/Command.js'
import { CommandType } from '../../utils/CommandType.js'

export class GetInstanceFieldHelper {
    /**
     * @param {Command | null | undefined} command
     * @param {string} fieldName
     * @returns {any}
     */
    static getFieldValue(command, fieldName) {
        if (!command || !command.payload || command.payload.length === 0) {
            return null
        }

        if (command.commandType === CommandType.SetInstanceField && command.payload.length >= 3) {
            const name = GetInstanceFieldHelper._getPayloadValue(command.payload[1])
            if (typeof name === 'string' && name === fieldName) {
                return GetInstanceFieldHelper._getPayloadValue(command.payload[2])
            }
        }

        if (command.commandType === CommandType.Array) {
            for (let i = 0; i < command.payload.length; i++) {
                const element = command.payload[i]
                if (element instanceof Command) {
                    const result = GetInstanceFieldHelper.getFieldValue(element, fieldName)
                    if (result !== null) {
                        return result
                    }
                }
            }
            return null
        }

        const firstPayload = command.payload[0]
        return firstPayload instanceof Command
            ? GetInstanceFieldHelper.getFieldValue(firstPayload, fieldName)
            : null
    }

    /**
     * @param {Command | null} command
     * @returns {string | null}
     * @throws {Error} if command is null or undefined
     */
    static getResultType(command) {
        if (!command) {
            throw new Error('GetInstanceFieldHelper.getResultType: command must not be null or undefined')
        }
        return GetInstanceFieldHelper._resolveResultType(command, 0)
    }

    /**
     * @param {any} node
     * @param {number} depth
     * @returns {string | null}
     */
    static _resolveResultType(node, depth) {
        if (node instanceof Command) {
            return GetInstanceFieldHelper._resolveCommandResultType(node, depth)
        }
        if (Array.isArray(node)) {
            return GetInstanceFieldHelper._resolvePayloadResultType(node, depth + 1)
        }
        return null
    }

    /**
     * @param {Command} command
     * @param {number} depth
     * @returns {string | null}
     */
    static _resolveCommandResultType(command, depth) {
        if (!command.payload || command.payload.length === 0) {
            return null
        }

        if (
            command.commandType === CommandType.GetResultType ||
            command.commandType === CommandType.GetType ||
            command.commandType === CommandType.ComplexValueType
        ) {
            const val = GetInstanceFieldHelper._getPayloadValue(command.payload[0])
            if (typeof val === 'string') {
                return GetInstanceFieldHelper._applyArrayDepth(val, depth)
            }
            return GetInstanceFieldHelper._resolveResultType(val, depth)
        }

        if (command.commandType === CommandType.Array) {
            return GetInstanceFieldHelper._resolvePayloadResultType(command.payload, depth + 1)
        }

        return GetInstanceFieldHelper._resolveResultType(command.payload[0], depth)
    }

    /**
     * @param {any[]} payload
     * @param {number} depth
     * @returns {string | null}
     */
    static _resolvePayloadResultType(payload, depth) {
        for (let i = 0; i < payload.length; i++) {
            const result = GetInstanceFieldHelper._resolveResultType(payload[i], depth)
            if (result !== null) {
                return result
            }
        }
        return null
    }

    /**
     * @param {string} typeName
     * @param {number} depth
     * @returns {string}
     */
    static _applyArrayDepth(typeName, depth) {
        if (depth <= 0) {
            return typeName
        }
        return typeName + '[]'.repeat(depth)
    }

    /**
     * @param {any} payloadItem
     * @returns {any}
     */
    static _getPayloadValue(payloadItem) {
        if (
            payloadItem instanceof Command &&
            payloadItem.commandType === CommandType.Value &&
            payloadItem.payload.length > 0
        ) {
            return payloadItem.payload[0]
        }
        return payloadItem
    }
}
